UPDATE public.questions AS t
   SET original_question_text = COALESCE(t.original_question_text, t.question_text),
       original_correct_answer = COALESCE(t.original_correct_answer, t.correct_answer),
       original_incorrect_answers = COALESCE(t.original_incorrect_answers, t.incorrect_answers),
       question_text = v.stem,
       correct_answer = v.correct,
       incorrect_answers = v.wrong,
       shorten_status = 'shortened'
  FROM (VALUES
    ('49d8a15f', 'What is a drainage basin with no outflow to the sea called?', 'Endorheic', '["Exorheic", "Ephemeral", "Dendritic"]'::jsonb),
    ('4d007ea4', 'Which TikTok feature records your video beside someone else''s?', 'Duet', '["Stitch", "Green Screen", "Voiceover"]'::jsonb),
