    ('62fa5c97', 'How is cuisine classified by geographic reach?', 'Continental, regional, local', '["Global, national, urban", "Traditional, modern, fusion", "Costly, moderate, budget"]'::jsonb),
    ('63838fb7', 'Which sitcom first got 11 straight Outstanding Comedy nods?', 'M*A*S*H', '["Frasier", "Seinfeld", "The Mary Tyler Moore Show"]'::jsonb),
    ('66dbab92', 'Which fast-fashion chain filed for Chapter 11 in 2019?', 'Forever 21', '["H&M", "Zara", "ASOS"]'::jsonb),
    ('67c51224', 'Which two seasonings did NASA make liquid for spaceflight?', 'Salt and pepper', '["Sriracha and ginger", "Cinnamon and nutmeg", "Vanilla and parsley"]'::jsonb),
    ('6b95eaed', 'Which concept behind positional notation came from ancient India?', 'Zero', '["Roman numerals", "Binary code", "Imaginary numbers"]'::jsonb),
    ('6d8c82cc', 'Who won the 2023 Best Actor Oscar for playing a physicist?', 'Cillian Murphy', '["Benedict Cumberbatch", "Daniel Day-Lewis", "Bradley Cooper"]'::jsonb),
    ('6e2e4b3c', 'Which metal are most US military service medals made from?', 'Bronze', '["Pure Gold", "Sterling Silver", "Stainless Steel"]'::jsonb),
    ('79f88c8d', 'Who directed the first feature with synchronised dialogue?', 'Alan Crosland', '["D.W. Griffith", "Charlie Chaplin", "F.W. Murnau"]'::jsonb),
    ('7a58ef1d', 'Which physics framework assumes absolute simultaneity?', 'Classical Mechanics', '["Quantum Electrodynamics", "General Relativity", "String Theory"]'::jsonb),
